<?php
// Included only after the published trip has been loaded.
if(!isset($t) || !function_exists('h')){http_response_code(404);exit;}
$d=tripDetails($t['id']);
$lines=static fn($s)=>array_values(array_filter(array_map('trim',preg_split('/\R/',(string)$s)),static fn($v)=>$v!==''));
$days=$lines($t['itinerary']);
$contact='?page=contact&id='.(int)$t['id'];
$photos=array_values(array_unique(array_merge([tripImage($t)],array_filter($lines($d['gallery']??''),static fn($v)=>filter_var($v,FILTER_VALIDATE_URL)&&str_starts_with($v,'https://')))));
?>
<div class="journey-v2">
<a class="j-back" href="?page=trips">← Explore all journeys</a>
<div class="j-gallery"><?php foreach($photos as $i=>$photo):?><a href="<?=h($photo)?>" target="_blank" rel="noopener" <?= $i?'hidden':''?>><img src="<?=h($photo)?>" alt="<?=h($t['title'])?> — destination inspiration <?=$i+1?>"></a><?php endforeach;?><span class="j-photo-label">Destination inspiration</span><?php if(count($photos)>1):?><button type="button" data-gallery-next>Next photo →</button><?php endif;?></div>
<div class="j-heading"><span class="eyebrow">THE NEXT CHAPTER / GROUP JOURNEYS</span><h1><?=h($t['title'])?></h1><p><?=h($t['description'])?></p><div class="j-facts"><span>Departure & route<br><strong><?=h($t['route'])?></strong></span><span>Travel dates<br><strong><?=h(preg_match('/\bproposed\b/i',(string)$t['dates'])?'Contact us for departure dates':$t['dates'])?></strong></span><span>Travel style<br><strong>Small group</strong></span></div></div>
<nav class="j-tabs" aria-label="Journey sections"><?php foreach(['itinerary'=>'Itinerary','details'=>'Details','included'=>'Inclusions','reviews'=>'Reviews','notices'=>'Notices'] as $key=>$label):?><a href="#j-<?=$key?>"><?=h($label)?></a><?php endforeach;?></nav>
<div class="j-layout"><div class="j-content">
<section id="j-itinerary"><div class="j-section-head"><h2>Your story unfolds</h2><?php if(is_file(__DIR__."/../private/itineraries/".(int)$t["id"].".pdf")): ?><a class="j-secondary" href="?page=itinerary-pdf&id=<?=(int)$t["id"]?>">↓ Download itinerary PDF</a><?php else: ?><button type="button" data-print>Print / save PDF</button><?php endif; ?></div><p class="j-muted">Explore your journey, day by day</p><?php foreach($days as $i=>$day): $parts=explode('|',$day,2);?><details class="j-day"><summary><span class="j-num"><?=sprintf('%02d',$i+1)?></span><strong><?=h(trim($parts[0]))?></strong><span class="j-plus">+</span></summary><?php if(!empty($parts[1])): ?><p><?=nl2br(h(trim($parts[1])))?></p><?php else: ?><p>Ask our team for the activities in this destination.</p><?php endif; ?></details><?php endforeach;?><div class="j-question"><strong>Curious about the pace of this journey?</strong><p>Ask about free time, accommodation or daily activities.</p><a href="<?=h($contact)?>">Talk to our team →</a></div></section>
<section id="j-details"><h2>About this journey</h2><p><?=nl2br(h($t['description']))?></p><h3>Meeting and return</h3><p><?=nl2br(h($d['meeting']??'Meeting point and return arrangements will be confirmed before departure.'))?></p><h3>Experiences</h3><?php foreach($lines($d['activities']??'') as $v):?><p>• <?=h($v)?></p><?php endforeach;?></section>
<section id="j-included"><h2>What is included</h2><?php foreach(['inclusions'=>'Included','exclusions'=>'Not included','optional_activities'=>'Optional experiences'] as $k=>$label):?><h3><?=h($label)?></h3><?php $items=$lines($k==='inclusions'?$t[$k]:($d[$k]??''));if(!$items):?><p class="j-muted">To be confirmed.</p><?php endif;?><ul class="j-checks"><?php foreach($items as $v):?><li><span aria-hidden="true"><?=$k==='inclusions'?'✓':($k==='exclusions'?'×':'+')?></span><?=h($v)?></li><?php endforeach;?></ul><?php endforeach;?></section>
<section id="j-reviews"><h2>Traveller stories</h2><?php premiumSetup();bookingSetup();$reviews=q("SELECT r.rating,r.body FROM onb_reviews r JOIN onb_bookings b ON b.id=r.booking_id AND b.user_id=r.user_id WHERE b.trip_id=? AND b.stage='completed' AND r.approved=1 ORDER BY r.booking_id DESC LIMIT 30",[$t['id']])->fetchAll();if(!$reviews):?><p>No verified reviews yet.</p><?php else:foreach($reviews as $review):?><article><strong><?=h($review['rating'])?> / 5 · Verified traveller</strong><p><?=nl2br(h($review['body']))?></p></article><?php endforeach;endif;?></section>
<section id="j-notices"><h2>Before you go</h2><p>Cancellation and refund conditions are specific to this journey. See the section below and our <a href="?page=policies#cancellation">general policy</a>.</p><?php foreach(journeyNotices($t['id']) as $label=>$body):?><details class="j-day"><summary><strong><?=h($label)?></strong><span class="j-plus">+</span></summary><p><?=nl2br(h($body))?></p></details><?php endforeach;?><?php foreach($lines($d['notices']??'') as $v):?><p><?=h($v)?></p><?php endforeach;?></section>
<section><h2>More journeys</h2><?php foreach(q('SELECT * FROM trips WHERE published=1 AND id<>? ORDER BY id DESC LIMIT 4',[$t['id']]) as $other):?><a class="j-related" href="?page=trip&id=<?=(int)$other['id']?>"><img loading="lazy" src="<?=h(tripImage($other))?>" alt=""><span><strong><?=h($other['title'])?></strong><br><?=h(preg_match('/\bproposed\b/i',(string)$other['dates'])?'Group journey':$other['dates'])?></span><span>→</span></a><?php endforeach;?></section>
</div><aside class="j-book"><span class="eyebrow">YOUR NEXT BOARDING</span><h2>Make it your story.</h2><p>Personalized pricing on request.</p><a class="j-primary" href="<?=h($contact)?>">Register interest →</a><?php departureSetup();if(q("SELECT 1 FROM onb_departures WHERE trip_id=? AND active=1 AND start_date>=CURRENT_DATE LIMIT 1",[$t['id']])->fetchColumn()):?><a class="j-secondary" href="?page=departures&amp;trip_id=<?=(int)$t['id']?>">View departures &amp; book</a><?php endif;?><small>No payment or commitment required.</small><button type="button" data-share>Share journey</button></aside></div></div>
